ClipboardLiveWorker::~ClipboardLiveWorker(){stop();}
void ClipboardLiveWorker::stop(){authorizationTick=0;{std::lock_guard<std::mutex>guard(mutex);stopping=true;}wake.notify_one();if(thread.joinable())thread.join();}
bool ClipboardLiveWorker::freshAuthority(uint64_t generation,uint64_t maxAge)const{auto a=std::atomic_load(&authority);auto tick=authorizationTick.load();return a&&current(a)&&generation==a->generation&&generation==authorizationGeneration.load()&&tick&&liveTick()-tick<=maxAge;}
