bool ClipboardLiveWorker::current(const std::shared_ptr<const ClipboardLiveAuthority>&a)const{auto live=std::atomic_load(&authority);auto c=callbacks.context();return a&&live==a&&c.authorized&&c.generation==a->generation;}
bool ClipboardLiveWorker::offer(std::string text,const ClipboardLiveContext&c){auto a=std::atomic_load(&authority);if(!current(a)||!c.authorized||!c.boardReadable||c.generation!=a->generation)return false;{std::lock_guard<std::mutex>guard(mutex);if(stopping)return false;latest=Copy{std::move(text),c};pendingFlag=true;++revision;}wake.notify_one();return true;}
