void ClipboardLiveWorker::compatibilityQueued(const Id&event){{std::lock_guard<std::mutex>guard(mutex);compatAcks.push_back(event);++revision;}wake.notify_one();}
bool ClipboardLiveWorker::knows(const Id&sender,const Id&event)const{auto j=snapshot();auto a=std::atomic_load(&authority);if(!a||j->at("scope").str()!=a->grant->scope)return false;return j->at("seen").has(uuidText(sender)+":"+uuidText(event));}
