   auto oldPending=store->current().at("outbox"),oldContext=store->current().at("outboxContext");for(const auto&row:store->current().at("compat").items)if(row.at("expiresAt").num()<=unixTime()&&row.has("context"))releasePending(row.at("context"),a);auto pending=store->pending(unixTime());if(oldPending.kind!=Json::Kind::null&&pending.kind==Json::Kind::null)releasePending(oldContext,a);if(copy){auto now=callbacks.context();if(copy->context.generation==a->generation&&copy->context.serial==now.serial&&copy->context.sequence==now.sequence&&now.boardReadable&&pending.kind==Json::Kind::null){store->stage(*a->grant,copy->text,unixTime(),Json::object({{"incarnation",a->incarnation},{"generation",copy->context.generation},{"serial",copy->context.serial},{"sequence",uint64_t(copy->context.sequence)}}));pending=store->pending(unixTime());}else if(pending.kind!=Json::Kind::null){std::lock_guard<std::mutex>guard(mutex);if(!latest)latest=std::move(copy);}}
